Algorithm IsPrimitive(F, Y, x):
  for each Z in Ob(C) with Z != Y:
    for each f in Hom(Y, Z):
      for each z in F(op Z):
        if F(f^op)(z) = x: return False
  return True

Algorithm GreedyCover(F):
  uncovered = all (W, w) pairs
  cover = []
  while uncovered != empty:
    best = argmax coverage among candidates
    cover.append(best)
    uncovered -= Coverage(best)
  return cover

Algorithm ExactMinCover(F):
  for k = 1 to totalSections(F):
    for each k-subset S of generators:
      if Coverage(S) covers all sections:
        return k
  return totalSections(F)
